DROP VIEW "public"."credential_access";
CREATE VIEW "public"."credential_access" AS (select "credential"."id", "user"."id" as "user_id", case when "user"."is_admin" = true then 'tenant-admin' when ("owner"."id" = "user"."id" or "credential_permission"."is_admin" = true) then 'admin' when "credential_permission"."is_admin" = false then 'read' else 'global' end as "access_level", "credential"."provider", "credential"."scope", "credential"."email", "credential"."is_global", json_build_object('id', "owner"."id", 'email', "owner"."email", 'pfpUrl', "owner"."pfp_url", 'displayName', "owner"."display_name", 'isTenantAdmin', "owner"."is_admin") as "owned_by", coalesce(json_agg(json_build_object('id', "perm_user"."id", 'displayName', "perm_user"."display_name", 'email', "perm_user"."email", 'pfpUrl', "perm_user"."pfp_url", 'accessLevel', case when "perm_user"."is_admin" = true then 'tenant-admin' when ("owner"."id" = "perm_user"."id" or "credential_permission"."is_admin" = true) then 'admin' when "credential_permission"."is_admin" = false then 'read' else 'global' end)) filter (where ("perm_user"."id" is not null and not "perm_user"."id" = "owner"."id")), '[]'::json) as "permissions", "credential"."access_token", "credential"."refresh_token", "credential"."created_at" from "credential" inner join "user" "owner" on "owner"."id" = "credential"."user_id" inner join "user" on "user"."slug" = "owner"."slug" left join "credential_permission" on ("credential_permission"."credential_id" = "credential"."id" and "credential_permission"."user_id" = "user"."id") left join "user" "perm_user" on ("perm_user"."slug" = "user"."slug" and ("perm_user"."id" = "credential_permission"."user_id" or "perm_user"."is_admin" = true)) where ("user"."is_admin" = true or "owner"."id" = "user"."id" or "perm_user"."id" is not null or "credential"."is_global" = true) group by "credential"."id", "user"."id", "owner"."id", "credential_permission"."is_admin");